// lib/ppt-assets.ts
//
// Embedded image assets for the uxproof presentation generator.
// All entries are full data:image/...;base64 URIs that pptxgenjs embeds
// directly into the .pptx (no external file dependencies).
//
// The PAISAK4U wordmark variants have proper transparency, so they
// composite correctly on white, graphite, and black backgrounds.
// LOGO aspect ratio is 1716:268 (~6.4:1) — keep w/h in that ratio
// wherever the wordmark is placed.

export const ASSETS = {
  // Black wordmark (for white / light backgrounds)
  LOGO_DARK: 'data:image/png;base64,',

  // White wordmark (for black / graphite backgrounds)
  LOGO_LIGHT: 'data:image/png;base64,',

  // Full-resolution black wordmark for the Thank You slide
  LOGO_BIG: 'data:image/png;base64,',

  // Default presentation image - right half of the cover slide
  COVER_IMAGE: 'data:image/jpeg;base64,',
};

/**
 * Throws a descriptive error if any required image is missing.
 * Called from generatePowerPoint to fail fast.
 */
export function assertAssetsReady(): void {
  const missing: string[] = [];
  for (const [name, value] of Object.entries(ASSETS)) {
    if (!value || value.length < 100 || !value.startsWith('data:image/')) {
      missing.push(name);
    }
  }
  if (missing.length) {
    throw new Error(
      `[ppt-assets] missing/invalid image data for: ${missing.join(', ')}. ` +
      `Each ASSETS entry must be a full "data:image/...;base64,..." URI.`,
    );
  }
}
